grammar Invalid {
 @package: commonprobe
 @whitespace: none
 @root @mapping(Node) @commonField(text,maybe,many,mode)
 Root ::= A | B;
 @enum Mode ::= 'on' | 'off';
 @mapping(A, params=[text,maybe,many,mode])
 A ::= 'a' '😀' @text '[' [ 'x' @maybe ] ']' '{' { 'z' @many } '}' Mode @mode;
 @mapping(B, params=[maybe,many,mode])
 B ::= 'b' 'é' '[' [ 'x' @maybe ] ']' '{' { 'z' @many } '}' Mode @mode;
}

